function main() {
    const lines = require('fs').readFileSync('/dev/stdin', 'utf8').split('\n');
    let lineIndex = 0;
    function readLine() { return lines[lineIndex++]; }
    function readInt() { return parseInt(readLine()); }
    function readLong() { return BigInt(readLine().trim()); }
    function readInts() { return readLine().split(" ").map(Number); }
    function readLongs() { return readLine().split(" ").map(BigInt); }

    const n = readInt();
    process.stdout.write(String(Math.floor(3 * n / 2)));
}

main();
